function anyPeak(nums: number[]): number {
  let lo = 0, hi = nums.length - 1; // [lo, hi] always contains a peak
  while (lo < hi) {
    const mid = (lo + hi) >> 1; // rounds down, so mid + 1 <= hi
    if (nums[mid] < nums[mid + 1]) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

